http:request.http:body:
#[output application/json
---
{
  model: "openai/gpt-oss-120b",
  messages: [
    { role: "system", content: "You are an order support assistant. Use a tool when you need order data. Never guess an order status." },
    { role: "user", content: vars.question }
  ],
  tools: [
    {
      "type": "function",
      "function": {
        name: "get_order_status",
        description: "Get the current status of a customer order by its order id.",
        parameters: {
          "type": "object",
          properties: {
            orderId: { "type": "string", description: "The order id, for example ORD-1042" }
          },
          required: ["orderId"]
        }
      }
    }
  ],
  tool_choice: "auto",
  stream: false
}]

ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
[
  {
    "type": "function",
    "function": {
      name: "get_order_status",
      description: "Get the current status of a customer order by its order id.",
      parameters: {
        "type": "object",
        properties: {
          orderId: { "type": "string", description: "The order id, for example ORD-1042" }
        },
        required: ["orderId"]
      }
    }
  }
]

ee:message.ee:set-payload:
%dw 2.0
output application/json
var orders = {
  "ORD-1042": { status: "PROCESSING", items: 3, shipped: false },
  "ORD-1043": { status: "SHIPPED", items: 1, shipped: true, carrier: "BlueDart" }
}
---
{ orderId: payload.orderId } ++ (orders[payload.orderId] default { status: "NOT_FOUND" })
